+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import com.vaadin.flow.component.grid.Grid;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * The seed (V2) holds six vets, sorted by last name here: Carter (no
+ * specialties), Douglas (surgery, dentistry), Jenkins (none), Leary
+ * (radiology), Ortega (surgery), Stevens (radiology).
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int SEEDED_VET_COUNT = 6;
+    private static final int FIRST_NAME_COLUMN = 0;
+    private static final int LAST_NAME_COLUMN = 1;
+    private static final int SPECIALTIES_COLUMN = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void vetsPageIsReachableWithoutAuthentication() {
+        // No login is performed, covering BR-003 (Anonymous Access).
+        assertDoesNotThrow(() -> navigate(VetsView.class),
+                "Expected the veterinarians route to resolve without authentication");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsEveryVetWithTheirSpecialties() {
+        navigate(VetsView.class);
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+
+        assertEquals(SEEDED_VET_COUNT, test(grid).size(), "Expected one row per seeded vet");
+        assertEquals("Carter", test(grid).getCellText(0, LAST_NAME_COLUMN));
+        assertEquals("Douglas", test(grid).getCellText(1, LAST_NAME_COLUMN));
+        assertEquals("Leary", test(grid).getCellText(3, LAST_NAME_COLUMN));
+        assertEquals("Helen", test(grid).getCellText(3, FIRST_NAME_COLUMN));
+        assertEquals("radiology", test(grid).getCellText(3, SPECIALTIES_COLUMN));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesOfAVetAreListedAlphabetically() {
+        // Seeded as surgery (id 2) then dentistry (id 3); alphabetical order reverses them.
+        navigate(VetsView.class);
+        Grid<?> grid = find(Grid.class).single();
+
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, SPECIALTIES_COLUMN));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetWithoutSpecialtiesShowsNone() {
+        navigate(VetsView.class);
+        Grid<?> grid = find(Grid.class).single();
+
+        assertEquals(VetsView.NO_SPECIALTIES, test(grid).getCellText(0, SPECIALTIES_COLUMN));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void rowsAreFetchedInWindowsAsTheGridScrolls() {
+        navigate(VetsView.class);
+        Grid<?> grid = find(Grid.class).single();
+
+        // The grid asks for rows by offset; a window in the middle must hold the right vets.
+        assertEquals(SEEDED_VET_COUNT, test(grid).size());
+        assertEquals("Jenkins", test(grid).getCellText(2, LAST_NAME_COLUMN));
+        assertEquals("Ortega", test(grid).getCellText(4, LAST_NAME_COLUMN));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyClinicRendersAnEmptyGrid() {
+        // Rolled back at test end, so the seed is intact for the next test.
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+        Grid<?> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected the veterinarians grid even when no vet is registered");
+
+        assertEquals(0, test(grid).size(), "Expected no rows when no vet is registered");
+    }
+}
